// Inspired by the goose programming language variable size enum 05_shapes.goose

use std::marker::PhantomData;

pub use bytemuck;
pub use variable_size_enum_macro::variable_enum;

// Marker Trait implemented by every structure generated by variable_enum
pub trait VariableEnum: Sized {
    type Kind: Copy;
    const MAX_SIZE: usize;

    fn kind(&self) -> Self::Kind;
    fn write_to_uninit(&self, out: &mut [::core::mem::MaybeUninit<u8>]) -> usize;
    fn from_bytes(bytes: &[u8]) -> (Self, usize);
}

pub struct VariableVec<T> {
    variable_enum: std::marker::PhantomData<T>,
    storage: Vec<u8>,
    pub len: usize,
}

impl<T> VariableVec<T>
where
    T: VariableEnum,
{
    pub fn new() -> Self {
        Self {
            variable_enum: PhantomData,
            storage: Vec::new(),
            len: 0,
        }
    }

    pub const fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub const fn len(&self) -> usize {
        self.len
    }

    pub const fn used_bytes(&self) -> usize {
        self.storage.len()
    }

    pub fn push(&mut self, item: T) {
        let start = self.storage.len();
        // Bump allocate size
        self.storage.reserve(T::MAX_SIZE);

        let spare = self.storage.spare_capacity_mut();
        let written = item.write_to_uninit(&mut spare[..T::MAX_SIZE]);

        // SAFETY: write_to_uninit guarantees 'written' bytes have been initialized
        unsafe {
            self.storage.set_len(start + written);
        }

        self.len += 1;
    }
}

impl<T> Default for VariableVec<T>
where
    T: VariableEnum,
{
    fn default() -> Self {
        Self::new()
    }
}

pub struct VariableVecIter<'a, T> {
    storage: &'a [u8],
    offset: usize,
    _marker: PhantomData<T>,
}

impl<T> VariableVec<T> {
    pub fn iter(&self) -> VariableVecIter<'_, T> {
        VariableVecIter {
            storage: &self.storage,
            offset: 0,
            _marker: PhantomData,
        }
    }
}

impl<T: VariableEnum> Iterator for VariableVecIter<'_, T> {
    type Item = T;

    fn next(&mut self) -> Option<Self::Item> {
        if self.offset >= self.storage.len() {
            return None;
        }

        let remaining = &self.storage[self.offset..];
        let (item, bytes_read) = T::from_bytes(remaining);

        debug_assert!(
            bytes_read > 0 && bytes_read <= remaining.len(),
            "invalid byte count returned by VariableEnum::from_bytes"
        );

        self.offset += bytes_read;

        Some(item)
    }
}

impl<'a, T: VariableEnum> IntoIterator for &'a VariableVec<T> {
    type Item = T;
    type IntoIter = VariableVecIter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}

pub fn test() -> u8 {
    1
}
